*{box-sizing:border-box} :root{--ink:#07141d;--paper:#edf7f5;--muted:#89a3aa;--cyan:#5af4e5;--lime:#d8ff69;--pink:#ff5da8;--mono:'Space Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper);font-family:var(--mono);overscroll-behavior:none}.game-shell{position:relative;width:100%;height:100dvh;min-height:520px;overflow:hidden;background:#081822;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,15,21,.58),transparent 22%,transparent 62%,rgba(4,13,18,.48)),linear-gradient(90deg,rgba(4,12,17,.32),transparent 30%,transparent 70%,rgba(4,12,17,.28));z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 clamp(20px,4vw,60px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(198,239,232,.12);background:linear-gradient(180deg,rgba(4,14,20,.62),transparent)}.brand{display:flex;align-items:center;gap:10px;color:#eff9f7;text-decoration:none;font:800 17px var(--display);letter-spacing:1.6px}.brand-icon{width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--cyan);color:var(--cyan);font:800 19px var(--display);transform:skew(-8deg)}.brand-slash{color:var(--cyan)}.route-tag{font-size:10px;color:#bed0d0;letter-spacing:1.6px}.live-dot{display:inline-block;width:6px;height:6px;background:var(--pink);border-radius:50%;margin-right:8px;box-shadow:0 0 12px var(--pink)}.route-sep{color:var(--cyan);padding:0 7px}.icon-btn{width:38px;height:38px;border:1px solid rgba(227,247,241,.3);background:rgba(9,24,31,.45);color:var(--paper);font:700 16px var(--mono);cursor:pointer}.hud{position:absolute;z-index:3;top:98px;left:clamp(20px,4vw,60px);right:clamp(20px,4vw,60px);display:flex;align-items:flex-start;gap:30px;pointer-events:none}.stat{display:flex;align-items:baseline;gap:6px}.stat-label{display:block;color:#a6bec0;font-size:9px;letter-spacing:1.5px}.score-stat{flex-wrap:wrap;column-gap:5px;width:120px}.score-stat .stat-label{width:100%;margin-bottom:1px}.stat strong{font:700 30px var(--display);letter-spacing:1px;color:#fff}.score-stat small{font-size:10px;color:var(--cyan)}.coin-stat{display:grid;grid-template-columns:16px auto;grid-template-rows:24px 12px;column-gap:7px}.coin-glyph{grid-row:1/3;align-self:center;color:var(--lime);font-size:18px;text-shadow:0 0 12px rgba(216,255,105,.65)}.coin-stat strong{font:700 24px var(--display);align-self:center}.coin-stat .stat-label{grid-column:2;font-size:8px}.charge-wrap{margin-left:auto;width:min(205px,23vw);padding-top:2px}.charge-label{display:flex;justify-content:space-between;color:#c1d4d1;font-size:8px;letter-spacing:1.1px}.charge-label span:last-child{color:var(--lime)}.charge-track{height:5px;margin-top:8px;background:rgba(205,235,228,.18);transform:skew(-18deg);overflow:hidden}.charge-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,#41d4d9,var(--lime));box-shadow:0 0 10px var(--cyan);transition:width .15s}.charge-hint{margin-top:5px;color:#8da5a5;font-size:7px;letter-spacing:.8px}.power-indicator{position:absolute;top:55px;right:0;border:1px solid rgba(90,244,229,.35);padding:7px 10px;color:var(--cyan);font-size:8px;letter-spacing:1px;display:flex;gap:7px;align-items:center;opacity:0;transition:opacity .2s}.power-indicator.active{opacity:1}.power-indicator span:first-child{font-size:14px}.toast{position:absolute;z-index:3;top:30%;left:50%;transform:translate(-50%,-10px);font:700 17px var(--display);letter-spacing:2px;color:var(--lime);text-shadow:0 2px 18px #000;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.center-screen{position:absolute;z-index:4;top:50%;left:50%;transform:translate(-50%,-45%);width:min(590px,90vw);text-align:center;padding:32px 28px;background:linear-gradient(135deg,rgba(5,18,24,.82),rgba(7,22,29,.54));border:1px solid rgba(134,233,220,.2);box-shadow:0 22px 100px rgba(0,0,0,.25);backdrop-filter:blur(8px)}.hidden{display:none}.eyebrow{display:flex;justify-content:center;align-items:center;gap:9px;color:var(--cyan);font-size:9px;letter-spacing:2.2px}.eyebrow span{width:22px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}h1,h2{margin:15px 0 8px;font:900 clamp(58px,9vw,95px)/.79 var(--display);letter-spacing:-1px;color:#f2fbf8;text-shadow:0 5px 35px rgba(2,10,14,.32)}h1 em,h2 em{font-style:normal;color:var(--cyan)}.intro{margin:22px 0 20px;font-size:11px;line-height:1.8;color:#b9cecc}.primary-btn{display:flex;align-items:center;justify-content:space-between;gap:40px;margin:0 auto;padding:0 19px;width:188px;height:48px;border:0;background:var(--lime);color:#15211a;font:700 12px var(--mono);letter-spacing:1px;cursor:pointer;box-shadow:0 0 24px rgba(216,255,105,.17);transition:transform .15s,box-shadow .15s}.primary-btn:hover{transform:translateY(-2px);box-shadow:0 8px 30px rgba(216,255,105,.25)}.primary-btn b{font-size:19px}.key-guide{display:flex;justify-content:center;align-items:center;gap:9px;margin:20px auto 0;color:#9eb4b3;font-size:8px;letter-spacing:.8px;white-space:nowrap}.key-guide kbd{display:inline-grid;place-items:center;min-width:19px;height:20px;margin-right:2px;padding:0 4px;border:1px solid rgba(197,235,227,.28);color:#eaf5f2;font:9px var(--mono);background:rgba(255,255,255,.04)}.key-guide i{width:3px;height:3px;background:var(--cyan);border-radius:50%;margin:0 5px}.new-mechanic{display:flex;justify-content:center;align-items:center;gap:10px;margin:21px auto 0;padding-top:13px;border-top:1px solid rgba(196,235,226,.13);text-align:left;width:max-content;max-width:100%}.new-mechanic .spark{color:var(--lime);font-size:20px}.new-mechanic b{display:block;color:var(--lime);font-size:8px;letter-spacing:1px}.new-mechanic small{display:block;margin-top:5px;color:#b3c5c2;font-size:8px}.new-mechanic kbd{border:1px solid rgba(197,235,227,.28);padding:2px 5px;color:#fff;font:8px var(--mono)}.center-screen h2{font-size:clamp(60px,9vw,88px)}.center-screen h2 span{color:var(--lime)}.results{display:flex;justify-content:center;gap:34px;margin:22px auto 25px}.results div{display:grid;gap:6px}.results small{font-size:8px;letter-spacing:1px;color:#a1b9b7}.results strong{font:700 27px var(--display);color:var(--lime)}.results strong span{font:10px var(--mono);color:#c1d5d0;margin-left:3px}.bottom-note{position:absolute;z-index:3;bottom:18px;left:clamp(20px,4vw,60px);right:clamp(20px,4vw,60px);display:flex;justify-content:space-between;color:#a4b9b9;font-size:8px;letter-spacing:1px;pointer-events:none}.bottom-note b{color:var(--cyan)}.mobile-controls{display:none}.game-shell.running .center-screen{display:none}
@media(max-width:700px){.game-shell{min-height:480px}.topbar{height:58px;padding:0 16px}.brand{font-size:14px}.brand-icon{width:25px;height:25px}.route-tag{font-size:7px;letter-spacing:.8px}.pause-btn{width:32px;height:32px}.hud{top:72px;left:17px;right:17px;gap:14px}.score-stat{width:88px}.stat strong{font-size:25px}.coin-stat strong{font-size:20px}.charge-wrap{width:115px;margin-top:2px}.charge-hint{font-size:6px}.power-indicator{top:48px}.center-screen{padding:27px 16px;transform:translate(-50%,-50%);width:min(510px,92vw)}h1{font-size:clamp(54px,15vw,80px)}.intro{font-size:10px;margin:18px 0}.key-guide{font-size:7px;gap:5px;margin-top:14px}.key-guide i{margin:0 1px}.new-mechanic{margin-top:15px}.bottom-note{display:none}.mobile-controls{position:absolute;z-index:3;display:flex;justify-content:space-between;align-items:flex-end;left:0;right:0;bottom:max(15px,env(safe-area-inset-bottom));padding:0 18px;pointer-events:none}.move-pad,.action-pad{display:flex;gap:8px;pointer-events:auto}.mobile-controls button{border:1px solid rgba(220,249,240,.3);background:rgba(8,24,31,.54);color:#ecfbf7;backdrop-filter:blur(5px);touch-action:none}.move-pad button{width:48px;height:48px;font:26px var(--mono);color:var(--cyan)}.action-pad{gap:6px}.action-pad button{width:48px;height:49px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px}.action-pad button span{font:18px var(--mono);line-height:20px}.action-pad button small{font:6px var(--mono);letter-spacing:.8px;color:#b6cdca}.action-pad .phase-button{border-color:rgba(216,255,105,.45);color:var(--lime)}.action-pad button:active,.move-pad button:active{background:rgba(90,244,229,.2)}.results{gap:19px}.results strong{font-size:24px}}
@media(max-height:650px) and (min-width:701px){.center-screen{padding:20px}.new-mechanic{margin-top:12px}.intro{margin:14px 0}.key-guide{margin-top:12px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {distance:$('distance'),coins:$('coins'),chargeFill:$('chargeFill'),chargeText:$('chargeText'),chargeHint:$('chargeHint'),powerIndicator:$('powerIndicator'),powerIcon:$('powerIcon'),powerName:$('powerName'),toast:$('toast'),start:$('startScreen'),pause:$('pauseScreen'),over:$('gameOverScreen')};
  const C = {cyan:'#5af4e5',lime:'#d8ff69',pink:'#ff5da8',orange:'#ffb55d',ink:'#07141d'};
  let W=0,H=0,dpr=1,last=0,raf=0,toastTimer=0;
  let state='ready',items=[],travel=0,spawnAt=24,score=0,shards=0,best=Number(localStorage.getItem('neonrun-best')||0);
  let speed=17,lane=1,targetLane=1,jumpY=0,jumpV=0,sliding=0,phase=0,charge=0,shield=0,magnet=0,chrono=0,shake=0,flash=0,elapsed=0;
  const laneX=[-1.62,0,1.62];
  const rand=(a,b)=>a+Math.random()*(b-a);
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function resize(){
    const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);
    canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  addEventListener('resize',resize,{passive:true});resize();
  function project(x,z,y=0){
    const horizon=H*.475, scale=(H*.76)/(z+14);
    return {x:W*.5+x*scale,y:horizon+scale*(2.45-y),s:scale};
  }
  function poly(points,fill,stroke=null,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
  function line(a,b,color,width=1){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
  function glow(color,blur){ctx.shadowColor=color;ctx.shadowBlur=blur;}
  function noGlow(){ctx.shadowBlur=0;}
  function drawBackground(t){
    const sky=ctx.createLinearGradient(0,0,0,H*.65);sky.addColorStop(0,'#0a1a29');sky.addColorStop(.55,'#16303b');sky.addColorStop(1,'#42605e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    const horizon=H*.475;
    // Distant city silhouette
    ctx.fillStyle='#102530';ctx.beginPath();ctx.moveTo(0,horizon+6);
    for(let x=0;x<=W+40;x+=40){const bh=18+((Math.sin(x*.027)+Math.cos(x*.011))*10+15);ctx.lineTo(x,horizon-bh);ctx.lineTo(x+13,horizon-bh);ctx.lineTo(x+13,horizon+6);}
    ctx.lineTo(W,horizon+20);ctx.lineTo(0,horizon+20);ctx.fill();
    // Station architecture framing the vanishing point
    const v={x:W*.5,y:horizon+7};
    const sideGradL=ctx.createLinearGradient(0,0,W*.35,0);sideGradL.addColorStop(0,'#0a1922');sideGradL.addColorStop(1,'#172d34');
    const sideGradR=ctx.createLinearGradient(W,0,W*.65,0);sideGradR.addColorStop(0,'#0a1922');sideGradR.addColorStop(1,'#172d34');
    poly([{x:0,y:H*.1},{x:W*.17,y:H*.13},v,{x:W*.25,y:H},{x:0,y:H}],sideGradL);
    poly([{x:W,y:H*.1},{x:W*.83,y:H*.13},v,{x:W*.75,y:H},{x:W,y:H}],sideGradR);
    // Ceiling girders converge toward the tunnel
    for(let i=0;i<7;i++){
      const x=i*W/6;line({x,y:H*.12},{x:W*.5+(x-W*.5)*.11,y:horizon+8},'rgba(125,190,183,.12)',1);
    }
    line({x:0,y:H*.14},{x:W,y:H*.14},'rgba(167,213,201,.15)',2);
    // Platform edge lights
    for(let side of [-1,1]){
      const a=project(side*5.05,0),b=project(side*5.05,100);
      line(a,b,'rgba(87,245,222,.3)',Math.max(1,a.s*.035));
      for(let z=8;z<100;z+=13){const p=project(side*5.05,z);ctx.fillStyle='rgba(90,244,229,.5)';ctx.fillRect(p.x-p.s*.07,p.y-p.s*.055,p.s*.14,p.s*.07);}
    }
    // Neon sign in the distance
    if(W>500){ctx.save();ctx.globalAlpha=.72;glow(C.cyan,11);ctx.strokeStyle='rgba(90,244,229,.48)';ctx.lineWidth=1;ctx.strokeRect(W*.438,horizon-22,W*.124,17);noGlow();ctx.fillStyle='#a5fff0';ctx.font=`700 ${Math.max(7,W*.009)}px monospace`;ctx.textAlign='center';ctx.fillText('LAST TRAIN  /  00:09',W*.5,horizon-10);ctx.restore();}
  }
  function drawTrack(){
    const near=project(0,0),far=project(0,145);const nearL=project(-4.9,0),nearR=project(4.9,0),farL=project(-4.9,145),farR=project(4.9,145);
    poly([farL,farR,nearR,nearL],'#1b3035');
    const edgeL=project(-5.3,0),edgeLF=project(-5.3,145),edgeR=project(5.3,0),edgeRF=project(5.3,145);
    poly([edgeLF,farL,nearL,edgeL],'#273b3b');poly([farR,edgeRF,edgeR,nearR],'#273b3b');
    // Tracks / rails and center lane seams
    for(let x of [-3.65,-2.72,-.68,.68,2.72,3.65]){
      const a=project(x,0),b=project(x,145);line(a,b,x%2===0?'rgba(147,201,187,.36)':'rgba(119,163,153,.22)',Math.max(1,a.s*(x%2===0?.045:.025)));
    }
    // Cross ties; movement creates convincing depth
    const offset=travel%3.1;
    for(let z=2.2-offset;z<145;z+=3.1){if(z<0)continue;const l=project(-3.9,z),r=project(3.9,z),d=project(0,z);const thick=Math.max(1.2,d.s*.09);ctx.strokeStyle='rgba(7,16,19,.65)';ctx.lineWidth=thick;line(l,r,'rgba(7,16,19,.72)',thick);}
    // Lane markers, dashed and dim
    for(let x of [-.81,.81]){for(let z=4-(travel%12);z<130;z+=12){if(z<0)continue;const a=project(x,z),b=project(x,z-5);line(a,b,'rgba(94,149,140,.19)',Math.max(1,a.s*.02));}}
    // foreground rail reflections
    const gl=ctx.createLinearGradient(0,H*.57,0,H);gl.addColorStop(0,'rgba(45,180,167,0)');gl.addColorStop(1,'rgba(45,180,167,.13)');ctx.fillStyle=gl;ctx.fillRect(0,H*.56,W,H*.44);
  }
  function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
  function drawShard(item,p){
    const bob=Math.sin(elapsed*5+item.seed)*p.s*.07, x=p.x,y=p.y-p.s*.62+bob,sz=p.s*.18;
    ctx.save();ctx.translate(x,y);ctx.rotate(elapsed*1.6+item.seed);glow(C.lime,13);
    poly([{x:0,y:-sz},{x:sz*.72,y:0},{x:0,y:sz},{x:-sz*.72,y:0}],C.lime,'rgba(255,255,255,.8)',1);noGlow();ctx.restore();
  }
  function drawPower(item,p){
    const y=p.y-p.s*.8,x=p.x,rad=Math.max(5,p.s*.22),t=elapsed*2+item.seed;
    ctx.save();ctx.translate(x,y);glow(item.color,16);ctx.strokeStyle=item.color;ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,rad*(1+Math.sin(t)*.12),0,Math.PI*2);ctx.stroke();ctx.fillStyle='rgba(8,24,31,.9)';ctx.beginPath();ctx.arc(0,0,rad*.72,0,Math.PI*2);ctx.fill();ctx.fillStyle=item.color;ctx.font=`bold ${Math.max(9,rad*1.1)}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(item.kind==='magnet'?'M':item.kind==='shield'?'S':'T',0,1);noGlow();ctx.restore();
  }
  function drawHazard(item,p){
    const s=p.s,x=p.x,y=p.y;ctx.save();
    if(item.kind==='crate'){
      const w=s*.82,h=s*.72,top=s*.18;const left=x-w/2,right=x+w/2,bottom=y-2;
      poly([{x:left,y:bottom-h},{x:left+top,y:bottom-h-top},{x:right+top*.55,y:bottom-h-top},{x:right,y:bottom-h}], '#d8733e','#ffb36c',1);
      poly([{x:left,y:bottom-h},{x:right,y:bottom-h},{x:right,y:bottom},{x:left,y:bottom}], '#994b38','#ff9c5e',1);
      poly([{x:right,y:bottom-h},{x:right+top*.55,y:bottom-h-top},{x:right+top*.55,y:bottom-top},{x:right,y:bottom}], '#683e3a','#d98656',1);
      line({x:left+s*.12,y:bottom-h*.5},{x:right-s*.12,y:bottom-h*.5},'rgba(255,215,165,.65)',Math.max(1,s*.04));
    } else if(item.kind==='gate'){
      const w=s*1.15,h=s*.92,base=y-2;
      rounded(x-w/2,base-h,w,h*.23,2,'#d54670','#ff8daa');
      rounded(x-w*.43,base-h*.77,w*.14,h*.74,2,'#9b3456','#ff6f9c');rounded(x+w*.29,base-h*.77,w*.14,h*.74,2,'#9b3456','#ff6f9c');
      for(let k=-2;k<=2;k++){const bx=x+k*w*.17;line({x:bx,y:base-h*.69},{x:bx,y:base-h*.08},'rgba(255,215,224,.7)',Math.max(1,s*.025));}
      glow(C.pink,8);line({x:x-w*.42,y:base-h*.08},{x:x+w*.42,y:base-h*.08},'#ff9fbc',Math.max(1,s*.04));noGlow();
    } else {
      const w=s*1.12,h=s*1.55,base=y-1;
      poly([{x:x-w*.5,y:base},{x:x-w*.5,y:base-h*.78},{x:x-w*.34,y:base-h},{x:x+w*.34,y:base-h},{x:x+w*.5,y:base-h*.78},{x:x+w*.5,y:base}], '#24545c','#61c9c0',1.2);
      rounded(x-w*.34,base-h*.72,w*.68,h*.36,4,'#102b36','#5ff4e4');
      ctx.fillStyle='rgba(141,254,232,.62)';for(let i=0;i<3;i++)ctx.fillRect(x-w*.25+i*w*.22,base-h*.68,w*.09,h*.25);
      ctx.fillStyle='#ebff78';ctx.fillRect(x-w*.31,base-h*.13,w*.11,Math.max(2,s*.06));ctx.fillRect(x+w*.2,base-h*.13,w*.11,Math.max(2,s*.06));
    }
    ctx.restore();
  }
  function drawItems(){
    const sorted=items.slice().sort((a,b)=>b.z-a.z);
    for(const item of sorted){if(item.z>145||item.z< -4)continue;const p=project(laneX[item.lane],item.z);if(item.kind==='shard')drawShard(item,p);else if(['magnet','shield','chrono'].includes(item.kind))drawPower(item,p);else drawHazard(item,p);}
  }

function drawRunner(){
  const base=project(laneX[Math.round(lane)],0), p=project(laneX[lane<1?0:lane>1?2:1],0,jumpY),s=p.s;
  const x=base.x,y=p.y,sc=s/48,run=Math.sin(elapsed*13), crouch=sliding>0?1:0;
  // soft foot shadow remains on the rails while hopping
  ctx.save();ctx.globalAlpha=clamp(1-jumpY*.27,.26,.7);ctx.fillStyle='#061117';ctx.beginPath();ctx.ellipse(base.x,base.y-2,s*.32,s*.095,0,0,Math.PI*2);ctx.fill();ctx.restore();
  ctx.save();ctx.translate(x,y);ctx.scale(sc,sc);if(crouch)ctx.translate(0,13);
  if(phase>0){ctx.globalAlpha=.42;glow(C.cyan,19);ctx.strokeStyle=C.cyan;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-42,25,48,0,0,Math.PI*2);ctx.stroke();noGlow();ctx.globalAlpha=.42;}
  const swing=sliding>0?0:run*9;
  // legs and hi-top runners
  ctx.lineCap='round';ctx.lineJoin='round';
  ctx.strokeStyle='#182a36';ctx.lineWidth=8;line({x:-6,y:-20},{x:-8+swing*.5,y:-4},ctx.strokeStyle,8);line({x:7,y:-20},{x:7-swing*.5,y:-5},ctx.strokeStyle,8);
  ctx.strokeStyle='#eff9ed';line({x:-8+swing*.5,y:-5},{x:-3+swing*.5,y:-2},ctx.strokeStyle,6);line({x:7-swing*.5,y:-5},{x:12-swing*.5,y:-2},ctx.strokeStyle,6);
  ctx.strokeStyle=C.pink;line({x:-8+swing*.5,y:-1},{x:-1+swing*.5,y:-1},ctx.strokeStyle,2);line({x:7-swing*.5,y:-1},{x:14-swing*.5,y:-1},ctx.strokeStyle,2);
  // body jacket, angled while moving
  ctx.save();ctx.rotate(targetLane>lane?-.08:targetLane<lane?.08:run*.025);
