  const trailLane=safe;
  for(let i=0;i<5;i++)addItem('shard',trailLane,at+2.7+i*2.7);
  // occasional trail bends into the adjacent safe lane
  if(order%4===2){for(let i=0;i<3;i++)addItem('shard',safe===1?2:1,at+14+i*2.6);}
